    void ApplyAccessibility()
    {
        if(!polishReady)return;var details=inventorySlots.Parent?.Controls.OfType<Panel>().FirstOrDefault(p=>p.Dock==DockStyle.Right);if(details is not null)details.Width=features.Polish.InventoryDetailWidth;if(!features.Polish.HighContrast){foreach(var pair in originalColors)if(!pair.Key.IsDisposed){pair.Key.BackColor=pair.Value.back;pair.Key.ForeColor=pair.Value.fore;}originalColors.Clear();return;}
        foreach(var control in originalColors.Keys.Where(c=>c.IsDisposed).ToList())originalColors.Remove(control);
        void Paint(Control control){if(control is not ClassicButton&&control is not ClassicTitle&&control is not ClassicBrand){if(!originalColors.ContainsKey(control))originalColors[control]=(control.BackColor,control.ForeColor);control.BackColor=Color.White;control.ForeColor=Color.Black;}if(control is DataGridView g){g.DefaultCellStyle.BackColor=Color.White;g.DefaultCellStyle.ForeColor=Color.Black;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(235,235,235);g.ColumnHeadersDefaultCellStyle.BackColor=Color.Black;g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.DefaultCellStyle.SelectionBackColor=Color.Navy;g.DefaultCellStyle.SelectionForeColor=Color.White;}foreach(Control child in control.Controls)Paint(child);}foreach(Control c in Controls)Paint(c);
    }
    void BulkItemActions()
    {
        var selected=store.Items().Where(i=>bulkStacks.Contains(ItemIdentity.Key(i))).ToList();if(selected.Count==0){MessageBox.Show("Ctrl-click stacks or choose Select visible stacks first.");return;}using var d=EntryDialog($"Bulk action • {selected.Count} stacks",out var fields);var action=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList};action.Items.AddRange(["Watch selected","Stop watching selected","Tag Keep","Tag Sell","Tag Upgrade","Tag For another character","Add owned quantities to selling plans"]);action.SelectedIndex=0;Field(fields,"Apply to selected exact stacks",action);fields.Controls.Add(new Label(){Text="Tags apply to the item name. Existing selling plans are skipped, not replaced. No inventory quantities are changed.",AutoSize=true,MaximumSize=new Size(540,0)});fields.Controls.Add(Button("Apply to selection",()=>{try{if(action.SelectedIndex<=1){var keys=selected.Select(ItemIdentity.Key).ToHashSet();store.ReplaceItems(store.Items().Select(i=>keys.Contains(ItemIdentity.Key(i))?i with{Watch=action.SelectedIndex==0}:i).ToList());}else if(action.SelectedIndex<=5){string tag=action.Text[4..];foreach(var i in selected.DistinctBy(i=>TextKey.Search(i.Name))){features.Memos.RemoveAll(m=>m.Profile==store.Profile&&TextKey.Search(m.Name)==TextKey.Search(i.Name)&&m.Notes.Length==0);var existing=features.Memos.FirstOrDefault(m=>m.Profile==store.Profile&&TextKey.Search(m.Name)==TextKey.Search(i.Name));if(existing is not null){features.Memos.Remove(existing);features.Memos.Add(existing with{Tag=tag});}else features.Memos.Add(new(Guid.NewGuid().ToString(),store.Profile,i.Name,tag,""));}SaveFeatures();}else{foreach(var i in selected.Where(i=>i.Quantity>0))if(!Workspace.Selling.Any(s=>s.Profile==store.Profile&&ItemIdentity.Key(s.Name,s.Variant)==ItemIdentity.Key(i)))Workspace.Selling.Add(new(Guid.NewGuid().ToString(),store.Profile,i.Name,i.Quantity){Variant=i.Variant});SaveFeatures();}bulkStacks.Clear();Render();d.Close();}catch(Exception e){MessageBox.Show(e.Message);}}));d.ShowDialog(this);
    }
    void RenderDuplicates()
    {
        if(!polishReady)return;SetColumns(duplicateGrid,["Kind","Item / exact variant","Details"]);var groups=features.Trades.Where(t=>t.Profile==store.Profile).GroupBy(t=>new{Key=ItemIdentity.Key(t.Name,t.Variant),t.Buy,t.Quantity,t.UnitPrice,t.Fees});foreach(var group in groups){var rows=group.OrderBy(t=>t.At).ToList();for(int i=1;i<rows.Count;i++)if(PolishTools.Duplicate(rows[i-1],rows[i]))duplicateGrid.Rows.Add("Possible repeated trade",rows[i].Name+" • "+rows[i].Variant,$"{rows[i-1].At.LocalDateTime:g} / {rows[i].At.LocalDateTime:g} • {rows[i].Quantity} × {TextKey.Mesos(rows[i].UnitPrice)}");}foreach(var group in Workspace.Shopping.Where(s=>s.Profile==store.Profile).GroupBy(s=>ItemIdentity.Key(s.Name,s.Variant)).Where(g=>g.Count()>1))duplicateGrid.Rows.Add("Overlapping shopping plans",group.First().Name+" • "+group.First().Variant,$"{group.Count()} plans • {group.Sum(s=>s.Quantity-s.Purchased)} units remaining total");duplicateGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;duplicateGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;
    }
    Form CreateBackupPreview(PersonalBackup backup)
    {
        backup.Validate();var d=new Form(){Text="Review backup recovery",Size=new Size(960,700),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=Back};var grid=Grid();SetColumns(grid,["Character / section","Item or setting","Current","Backup"]);var current=store.AllInventories();var incoming=backup.Version>=2?backup.Characters!:[new CharacterInventory(new("main","Main character",0),backup.Items)];foreach(var id in current.Select(c=>c.Character.Id).Union(incoming.Select(c=>c.Character.Id))){var old=current.FirstOrDefault(c=>c.Character.Id==id);var next=incoming.FirstOrDefault(c=>c.Character.Id==id);string label=next?.Character.Name??old!.Character.Name;if(old?.Character!=next?.Character)grid.Rows.Add(label,"Profile / mesos",old is null?"Not present":old.Character.Name+" / "+TextKey.Mesos(old.Character.Mesos),next is null?"Removed":next.Character.Name+" / "+TextKey.Mesos(next.Character.Mesos));var a=(old?.Items??[]).ToDictionary(ItemIdentity.Key);var b=(next?.Items??[]).ToDictionary(ItemIdentity.Key);foreach(var key in a.Keys.Union(b.Keys)){a.TryGetValue(key,out var x);b.TryGetValue(key,out var y);if(x!=y)grid.Rows.Add(label,(y??x)!.ToString(),x is null?"Absent":$"Qty {x.Quantity} • watch {x.Watch} • mute {x.Muted}",y is null?"Removed":$"Qty {y.Quantity} • watch {y.Watch} • mute {y.Muted}");}}
        void CompareRecords<T>(string section,IEnumerable<T> old,IEnumerable<T> next,Func<T,string> id,Func<T,string> describe){var left=old.ToDictionary(id);var right=next.ToDictionary(id);foreach(var key in left.Keys.Union(right.Keys)){bool hasLeft=left.TryGetValue(key,out var x),hasRight=right.TryGetValue(key,out var y);if(hasLeft&&hasRight&&EqualityComparer<T>.Default.Equals(x!,y!))continue;grid.Rows.Add(section,hasRight?describe(y!):describe(x!),hasLeft?describe(x!):"Not present",hasRight?describe(y!):"Removed");}}
        CompareRecords("Trade journal",features.Trades,backup.Features.Trades,x=>x.Id,x=>$"{(x.Buy?"Buy":"Sell")} {x.Name} • {x.Variant} • {x.Quantity} × {x.UnitPrice} • fees {x.Fees} • {x.At.LocalDateTime:g}");
        CompareRecords("Shopping plans",Workspace.Shopping,backup.Features.Workspace.Shopping,x=>x.Id,x=>$"{x.Name} • {x.Variant} • {x.Purchased}/{x.Quantity} purchased • budget {x.Budget}");
        CompareRecords("Selling plans",Workspace.Selling,backup.Features.Workspace.Selling,x=>x.Id,x=>$"{x.Name} • {x.Variant} • quantity {x.Quantity}");
        CompareRecords("Item notes",features.Memos,backup.Features.Memos,x=>x.Id,x=>$"{x.Name} • {x.Tag} • {x.Notes}");
        CompareRecords("Goals",features.Goals,backup.Features.Goals,x=>x.Id,x=>$"{x.Name} • target {x.Target}");
        foreach(var property in typeof(CompanionFeatures).GetProperties().Where(p=>p.CanRead&&!p.GetMethod!.IsStatic&&!new[]{"Trades","Memos","Goals"}.Contains(p.Name))){var a=JsonSerializer.Serialize(property.GetValue(features),Json.Options);var b=JsonSerializer.Serialize(property.GetValue(backup.Features),Json.Options);if(a!=b){int n=grid.Rows.Add("Other preferences / records",property.Name,"Current settings (double-click to inspect)","Replaced by backup (double-click to inspect)");grid.Rows[n].Tag=(a,b);}}
        grid.CellDoubleClick+=(_,e)=>{if(e.RowIndex<0||grid.Rows[e.RowIndex].Tag is not ValueTuple<string,string> details)return;using var view=new Form(){Text="Current / backup values",Size=new Size(900,650),StartPosition=FormStartPosition.CenterParent};var panels=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=2};panels.ColumnStyles.Add(new(SizeType.Percent,50));panels.ColumnStyles.Add(new(SizeType.Percent,50));foreach(var value in new[]{details.Item1,details.Item2})panels.Controls.Add(new RichTextBox(){Dock=DockStyle.Fill,ReadOnly=true,Text=value,Font=new Font("Consolas",10)});view.Controls.Add(panels);view.ShowDialog(d);};
        if(JsonSerializer.Serialize(store.Transfers(),Json.Options)!=JsonSerializer.Serialize(backup.Transfers,Json.Options))grid.Rows.Add("History","Transfers",store.Transfers().Count,backup.Transfers.Count);grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;var actions=new FlowLayoutPanel(){Dock=DockStyle.Bottom,Height=52};actions.Controls.Add(Button("Restore this backup",()=>{d.DialogResult=DialogResult.OK;d.Close();}));actions.Controls.Add(Button("Cancel",()=>d.Close()));var note=Info(70);note.Text=$"{grid.Rows.Count} differences. This replaces personal data across all profiles, including journal, plans and preferences. Market cache is unchanged. A recovery copy is saved first; undo history is cleared. Cancel leaves everything unchanged.";d.Controls.Add(grid);d.Controls.Add(note);d.Controls.Add(actions);return d;
    }
    async Task SmokePolish()
    {
        var before=Snapshot();var first=new SavedItem("Test Variant Sword",1,false,false){Variant="watk=42; remaining=7"};var second=first with{Quantity=2,Variant="watk=48; remaining=2"};store.SaveItem(first);store.SaveItem(second);Render();selectedInventoryName=ItemIdentity.Key(second);if(CurrentInventory()?.Variant!=second.Variant)throw new Exception("Variant selection failed");store.SaveItem(first with{Quantity=4});if(store.Items().Single(i=>ItemIdentity.Key(i)==ItemIdentity.Key(second)).Quantity!=2)throw new Exception("Variant edit contaminated other stack");features.Polish.Aliases["my sword"]="Test Variant Sword";if(!PolishTools.Similar(features.Polish.Resolve("my sword"),first.Name))throw new Exception("Alias failed");bulkStacks.Add(ItemIdentity.Key(first));bulkStacks.Add(ItemIdentity.Key(second));features.Polish.SlotSize=80;RenderInventorySlots();ShowPage("Inventory");CapturePreview(Path.Combine(dataDirectory,"variants-14.png"));using(var preview=CreateBackupPreview(before)){preview.Show(this);using var shot=new Bitmap(preview.Width,preview.Height);preview.DrawToBitmap(shot,new Rectangle(Point.Empty,preview.Size));shot.Save(Path.Combine(dataDirectory,"backup-preview-14.png"));preview.Close();}features.Polish.HighContrast=true;ApplyAccessibility();CapturePreview(Path.Combine(dataDirectory,"contrast-14.png"));RestorePersonal(before);bulkStacks.Clear();Render();await Task.CompletedTask;
    }
